model.view:
{
  "version": 1,
  "state": [
    {
      "id": "success",
      "when": {
        "eq": [
          {
            "var": "record"
          },
          "\"success\""
        ]
      },
      "label": "Recovered successfully"
    },
    {
      "id": "failed",
      "when": {
        "eq": [
          {
            "var": "record"
          },
          "\"failed\""
        ]
      },
      "label": "Failed; source retained"
    },
    {
      "id": "offline",
      "when": {
        "eq": [
          {
            "var": "online"
          },
          "FALSE"
        ]
      },
      "label": "Interrupted; record retained"
    },
    {
      "id": "recovering",
      "when": {
        "eq": [
          {
            "var": "recovering"
          },
          "TRUE"
        ]
      },
      "label": "Resolve outstanding command"
    },
    {
      "id": "running",
      "when": {
        "eq": [
          {
            "var": "execution"
          },
          "\"running\""
        ]
      },
      "label": "Original command in progress"
    },
    {
      "id": "all",
      "when": true,
      "label": "Await or record the caller's result"
    }
  ],
  "step": [
    {
      "id": "crash",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Crash"
        ]
      },
      "label": "Interrupt"
    },
    {
      "id": "resume",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Resume"
        ]
      },
      "label": "Resume"
    },
    {
      "id": "drive",
      "when": {
        "eq": [
          {
            "action": true
          },
          "Drive"
        ]
      },
      "label": "Decide recovery or record result"
    },
    {
      "id": "accept",
      "when": {
        "eq": [
          {
            "action": true
          },
          "AcceptCommand"
        ]
      },
      "label": "Caller accepts the same command"
    },
    {
      "id": "observe",
      "when": {
        "eq": [
          {
            "action": true
          },
          "ObserveCommand"
        ]
      },
      "label": "Caller reconciles the command"
    },
    {
      "id": "finish",
      "when": {
        "eq": [
          {
            "action": true
          },
          "FinishCommand"
        ]
      },
      "label": "Caller finishes the original command"
    },
    {
      "id": "result",
      "when": {
        "eq": [
          {
            "action": true
          },
          "DeliverResult"
        ]
      },
      "label": "Caller supplies its result"
    },
    {
      "id": "all",
      "when": true,
      "label": "Report failure or retain the terminal record"
    }
  ]
}

